import { useCallback, useEffect, useState } from 'react'

// ---------------------------------------------------------------------------
// useHashRoute — tiny hash router.
//
// Hash routing keeps deep links working on any static host (Vercel, preview,
// file://) without adding react-router:
//   #/catalog          #/favorites       #/drafts      #/archived
//   #/profile          #/profile/edit
//   #/create           #/edit/:id        #/gun/:id
//
// Contact now lives on the profile page. Old #/contact links redirect there.
// Share links generated by utils/helpers#buildGunShareUrl point at #/gun/:id.
// ---------------------------------------------------------------------------

const DEFAULT_ROUTE = { name: 'catalog', id: null }

const KNOWN_TOP_LEVEL = new Set([
  'catalog',
  'favorites',
  'drafts',
  'archived',
  'profile',
  'create',
])

export const parseHash = (hash = '') => {
  const clean = String(hash)
    .replace(/^#/, '')
    .replace(/^\/+/, '')
  const path = clean.split('?')[0]
  const segments = path.split('/').filter(Boolean)

  if (segments.length === 0) return DEFAULT_ROUTE

  const [head, second] = segments

  if (head === 'gun' && second) {
    return { name: 'gun', id: decodeURIComponent(second) }
  }
  if (head === 'edit' && second) {
    return { name: 'edit', id: decodeURIComponent(second) }
  }
  if (head === 'profile' && second === 'edit') {
    return { name: 'profile-edit', id: null }
  }
  if (head === 'contact') {
    // Contact page removed — keep old links working.
    return { name: 'profile', id: null }
  }
  if (KNOWN_TOP_LEVEL.has(head)) {
    return { name: head, id: null }
  }

  return DEFAULT_ROUTE
}

export const buildHash = (target) => {
  const path = String(target || 'catalog').replace(/^#?\/+/, '')
  return `#/${path}`
}

export function useHashRoute() {
  const [route, setRoute] = useState(() => parseHash(window.location.hash))

  useEffect(() => {
    const onChange = () => setRoute(parseHash(window.location.hash))
    window.addEventListener('hashchange', onChange)
    return () => window.removeEventListener('hashchange', onChange)
  }, [])

  const navigate = useCallback((target) => {
    const nextHash = buildHash(target)
    if (window.location.hash === nextHash) {
      // Same hash — force a route refresh so callers can "re-open" a view.
      setRoute(parseHash(nextHash))
      return
    }
    window.location.hash = nextHash
  }, [])

  return { route, navigate }
}
